// Regenerates /public/bm/icons.css and /public/bm/icons.js from server/platform/icons.mjs.
// Run after adding or changing an icon: node scripts/build-icons.mjs
import {writeFileSync} from 'node:fs';
import {ICONS, GLYPHS, iconsCSS} from '../server/platform/icons.mjs';
writeFileSync('public/bm/icons.css', iconsCSS());
const js = `'use strict';
// Brazil Migration icon library — generated by scripts/build-icons.mjs. Do not edit by hand.
// Turns text glyphs (↗ ✓ ⌄ × ☰ ☾ 💡 …) into icons from /bm/icons.css, including content added later by scripts.
(() => {
  if (window.BMIcons) return;
  const G = ${JSON.stringify(GLYPHS)};
  const NAMES = ${JSON.stringify(Object.keys(ICONS))};
  if (!document.querySelector('link[href^="/bm/icons.css"]')) { const l = document.createElement('link'); l.rel = 'stylesheet'; l.href = '/bm/icons.css?v=${Date.now().toString(36)}'; document.head.appendChild(l); }
  const keys = Object.keys(G).sort((a, b) => b.length - a.length).map(k => k.replace(/[.*+?^\${}()|[\\]\\\\]/g, '\\\\$&'));
  const RE = new RegExp('(' + keys.join('|') + ')\\\\uFE0F?', 'gu'), TEST = new RegExp(keys.join('|'), 'u');
  const SKIP = /^(SCRIPT|STYLE|TEXTAREA|OPTION|SELECT|TITLE|INPUT|CODE|PRE|SVG|BM-I|NOSCRIPT)$/;
  const isMath = (s, i, len) => { const p = s.slice(0, i).trimEnd().slice(-1), n = s.slice(i + len).trimStart()[0] || ''; return /[\\p{L}\\d)]/u.test(p) && /[\\d(]/.test(n); };
  const icon = name => { const e = document.createElement('bm-i'); e.className = 'ic ic-' + name; e.setAttribute('aria-hidden', 'true'); return e; };
  function swap(t) {
    const s = t.nodeValue; if (!s || !TEST.test(s)) return;
    for (let p = t.parentNode; p && p !== document.body; p = p.parentNode) if (p.nodeType === 1 && (SKIP.test(p.nodeName.toUpperCase()) || p.isContentEditable || p.hasAttribute('data-no-icons'))) return;
    const f = document.createDocumentFragment(); let last = 0, hit = false;
    s.replace(RE, (m, g, i) => { if (g === '×' && isMath(s, i, m.length)) return m; hit = true; if (i > last) f.appendChild(document.createTextNode(s.slice(last, i))); f.appendChild(icon(G[g])); last = i + m.length; return m; });
    if (!hit) return;
    if (last < s.length) f.appendChild(document.createTextNode(s.slice(last)));
    t.parentNode.replaceChild(f, t);
  }
  function scan(root) {
    if (root.nodeType === 3) return swap(root);
    if (root.nodeType !== 1 || SKIP.test(root.nodeName.toUpperCase())) return;
    const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT), list = [];
    while (w.nextNode()) if (TEST.test(w.currentNode.nodeValue)) list.push(w.currentNode);
    list.forEach(swap);
  }
  const run = () => {
    scan(document.body);
    new MutationObserver(ms => { for (const m of ms) { if (m.type === 'characterData') swap(m.target); else m.addedNodes.forEach(scan); } }).observe(document.body, {childList: true, subtree: true, characterData: true});
  };
  window.BMIcons = {names: NAMES, glyphs: G, scan, el: icon};
  if (document.body) run(); else document.addEventListener('DOMContentLoaded', run);
})();
`;
writeFileSync('public/bm/icons.js', js);
console.log('icons:', Object.keys(ICONS).length, 'glyphs:', Object.keys(GLYPHS).length);
